#include <Security/Security.h>
#include <CoreFoundation/CoreFoundation.h>
#include <stdio.h>
#include <stdlib.h>
int main(int argc,char **argv){if(argc!=2)return 2;SecKeychainRef kc=NULL;const char *pw="synthetic-only";OSStatus st=SecKeychainCreate(argv[1],14,pw,0,NULL,&kc);printf("temporary_keychain_create_osstatus=%d\n",(int)st);if(st)return 1;size_t sizes[]={0,1024,4*1024*1024+16384};for(int i=0;i<3;i++){size_t n=sizes[i];UInt8 *buffer=calloc(n?n:1,1);if(!buffer){SecKeychainDelete(kc);CFRelease(kc);return 3;}CFDataRef value=CFDataCreate(NULL,buffer,n);free(buffer);CFMutableDictionaryRef q=CFDictionaryCreateMutable(NULL,0,&kCFTypeDictionaryKeyCallBacks,&kCFTypeDictionaryValueCallBacks);CFDictionarySetValue(q,kSecClass,kSecClassGenericPassword);CFDictionarySetValue(q,kSecAttrService,CFSTR("cadence.synthetic.limits"));CFDictionarySetValue(q,kSecAttrAccount,CFSTR("public-zeroes-only"));CFDictionarySetValue(q,kSecAttrSynchronizable,kCFBooleanFalse);CFMutableDictionaryRef add=CFDictionaryCreateMutableCopy(NULL,0,q);CFDictionarySetValue(add,kSecUseKeychain,kc);CFDictionarySetValue(add,kSecValueData,value);st=SecItemAdd(add,NULL);printf("synthetic_bytes=%zu add_osstatus=%d\n",n,(int)st);if(st==0){const void *list[]={kc};CFArrayRef search=CFArrayCreate(NULL,list,1,&kCFTypeArrayCallBacks);CFDictionarySetValue(q,kSecMatchSearchList,search);CFDictionarySetValue(q,kSecReturnData,kCFBooleanTrue);CFTypeRef result=NULL;OSStatus read=SecItemCopyMatching(q,&result);long actual=(read==0&&result&&CFGetTypeID(result)==CFDataGetTypeID())?CFDataGetLength((CFDataRef)result):-1;printf("read_osstatus=%d bytes=%ld\n",(int)read,actual);if(result)CFRelease(result);CFDictionaryRemoveValue(q,kSecReturnData);OSStatus del=SecItemDelete(q);printf("cleanup_osstatus=%d\n",(int)del);CFRelease(search);}CFRelease(add);CFRelease(q);CFRelease(value);}st=SecKeychainDelete(kc);printf("temporary_keychain_delete_osstatus=%d\n",(int)st);CFRelease(kc);return st==errSecSuccess?0:1;}
